import React, { useEffect, useState } from "react";
import Log from "./logger";

function App() {

  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);

  // simple priority logic
  const getScore = (item) => {
  let score = 0;

  if (item.type === "Placement") score += 3;
  else if (item.type === "Result") score += 2;
  else score += 1;

  // convert timestamp to number
  const time = new Date(item.timestamp).getTime();

  return score * 1000000000000 + time;
};

  useEffect(() => {

    const getData = async () => {
      try {

        Log("frontend", "info", "api", "getting notifications");

        const result = {
  notifications: [
    {
      id: "1",
      type: "Result",
      message: "mid-sem",
      timestamp: "2026-04-22 17:51:30"
    },
    {
      id: "2",
      type: "Placement",
      message: "CSX Corporation hiring",
      timestamp: "2026-04-22 17:51:18"
    },
    {
      id: "3",
      type: "Event",
      message: "farewell",
      timestamp: "2026-04-22 17:51:06"
    },
    {
      id: "4",
      type: "Result",
      message: "mid-sem",
      timestamp: "2026-04-22 17:50:54"
    },
    {
      id: "5",
      type: "Result",
      message: "project review",
      timestamp: "2026-04-22 17:50:42"
    },
    {
      id: "6",
      type: "Result",
      message: "external",
      timestamp: "2026-04-22 17:50:30"
    },
    {
      id: "7",
      type: "Result",
      message: "project review",
      timestamp: "2026-04-22 17:50:18"
    },
    {
      id: "8",
      type: "Event",
      message: "tech fest",
      timestamp: "2026-04-22 17:50:06"
    },
    {
      id: "9",
      type: "Result",
      message: "project review",
      timestamp: "2026-04-22 17:49:54"
    },
    {
      id: "10",
      type: "Placement",
      message: "Advanced Micro Devices Inc. hiring",
      timestamp: "2026-04-22 17:49:42"
    }
  ]
};

        Log("frontend", "info", "api", "data received");

        // sort based on priority
        let sortedData = result.notifications.sort((a, b) => {
          return getScore(b) - getScore(a);
        });

        // take top 10
        sortedData = sortedData.slice(0, 10);

        setData(sortedData);
        setLoading(false);

      } catch (e) {

        Log("frontend", "error", "api", "error while fetching");

        setLoading(false);
      }
    };

    getData();

  }, []);

  return (
  <div style={{ padding: "20px", fontFamily: "Arial" }}>
    <h2 style={{ marginBottom: "20px" }}>Notifications</h2>

    {loading ? (
      <p>Loading...</p>
    ) : data.length === 0 ? (
      <p>No notifications available</p>
    ) : (
      <div>
        {data.map((item) => {
          let color = "#ddd";

          if (item.type === "Placement") color = "#c8f7c5";
          else if (item.type === "Result") color = "#ffe4b5";
          else color = "#e0f0ff";

          return (
            <div
              key={item.id}
              style={{
                background: color,
                padding: "12px",
                marginBottom: "10px",
                borderRadius: "8px",
                boxShadow: "0 2px 5px rgba(0,0,0,0.1)",
              }}
            >
              <strong>{item.type}</strong> - {item.message}
              <br />
              <small>{item.timestamp}</small>
            </div>
          );
        })}
      </div>
    )}
  </div>
);
}

export default App;
